#include "mouth_dense_budget.hpp"
#include <cassert>
#include <iostream>

int main() {
    using namespace dense_budget;
    Budget ledger;
    double w[2] = {.75,.25};
    Vec velocity[2] = {{2,0,0,1},{-3,0,0,-1}};
    for (int i=0; i<2; ++i) ledger.start(i, w[i], velocity[i], 1);
    auto pair = [&](double image_b, const Vec& impulse) {
        ledger.pair_kick(crossings(w[0],image_b,0,1),
                         crossings(w[0],image_b,.5,1), impulse);
        add(velocity[0],impulse); add(velocity[1],impulse,-1);
    };
    auto drift = [&](double t) {
        for (int i=0; i<2; ++i) {
            double next = w[i] + t*velocity[i][3];
            ledger.drift(w[i],next,velocity[i],1);
            w[i]=next;
        }
    };
    pair(1.25, Vec{.375,0,0,0});
    Vec drive{.125,.25,0,0}, wall{0,-.375,.25,0};
    ledger.kick_mobile(w[1],drive,wall,1);
    add(velocity[1],drive); add(velocity[1],wall);
    drift(.375);
    Vec noise{-.125,.25,-.375,0};
    ledger.bath(w[0],noise,1); add(velocity[0],noise);
    pair(w[1],Vec{.125,.25,.375,0});
    drift(1.5);
    for (int i=0; i<2; ++i) ledger.finish(i,w[i],velocity[i],1);
    assert(inside(0,1) && !inside(.5,1) && !inside(-.5,1));
    assert(crossings(-.5,.5,.5,1)==1 && crossings(.5,-.5,.5,1)==-1);
    ledger.json(std::cout);
}

